CREATE TABLE friendship(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),friend_id TEXT NOT NULL REFERENCES user(id),status TEXT DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,friend_id));
CREATE TABLE friend_status(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL REFERENCES user(id),friend_id TEXT NOT NULL REFERENCES user(id),given INTEGER DEFAULT 0,recvd INTEGER DEFAULT 0,nickname TEXT NOT NULL DEFAULT '',when_created INTEGER NOT NULL,level INTEGER DEFAULT 1,abilities TEXT,hints TEXT,outfit TEXT,player_badge_type INTEGER DEFAULT 0,local_soft_deleted BOOLEAN DEFAULT 0,attitude TEXT DEFAULT '0',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,friend_id));
